package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.*;
public class DirectClientStartupTest {
 Map<String,Object> waiting(){return Map.of("success",false,"state","condition_timeout","outcome_unknown",false,"action_dispatched",false);}
 @Test public void lateWindowIsObservedAgainWithoutLaunchingAnotherClient()throws Exception{var probes=new AtomicInteger();var verify=new AtomicInteger();var clock=new AtomicLong();var r=DirectClientStartup.await(ms->{assertTrue(ms<=10000);return probes.incrementAndGet()==1?waiting():Map.of("success",true);},verify::incrementAndGet,10,()->clock.getAndAdd(1000000));assertEquals(true,r.get("ready"));assertEquals(2,probes.get());assertEquals(3,verify.get());}
 @Test public void coldStartupReceivesWholeRemainingBudget()throws Exception{var budget=new AtomicInteger();var r=DirectClientStartup.await(ms->{budget.set(ms);return Map.of("success",true);},()->{},90,System::nanoTime);assertTrue(budget.get()>80000);assertTrue(budget.get()<=90000);assertEquals(true,r.get("ready"));}
 @Test public void readinessTimeoutRemainsBoundedAndNeverRetrySafe()throws Exception{var calls=new AtomicInteger();var clock=new AtomicLong();var r=DirectClientStartup.await(ms->{calls.incrementAndGet();return waiting();},()->{},1,()->clock.getAndAdd(100000000));assertEquals("startup_ui_timeout",r.get("state"));assertEquals(false,r.get("ready"));assertEquals(false,r.get("retry_safe"));assertTrue(calls.get()>1);assertTrue(calls.get()<10);}
 @Test public void unknownTransportIsNeverRetried()throws Exception{var calls=new AtomicInteger();var r=DirectClientStartup.await(ms->{calls.incrementAndGet();return Map.of("success",false,"state","transport_failed","outcome_unknown",true);},()->{},10,System::nanoTime);assertEquals("startup_transport_unavailable",r.get("state"));assertEquals(1,calls.get());}
 @Test public void ambiguousReadOnlyOutcomeIsNotRetried()throws Exception{var calls=new AtomicInteger();var r=DirectClientStartup.await(ms->{calls.incrementAndGet();return Map.of("success",false,"state","condition_timeout");},()->{},10,System::nanoTime);assertEquals(false,r.get("ready"));assertEquals(1,calls.get());}
 @Test public void bindingOrProcessChangeAbortsBeforeAnotherRead()throws Exception{var calls=new AtomicInteger();try{DirectClientStartup.await(ms->{calls.incrementAndGet();return Map.of("success",true);},()->{throw new IllegalStateException("changed");},10,System::nanoTime);fail();}catch(IllegalStateException expected){}assertEquals(0,calls.get());}
 @Test public void timeoutAndClientKindAreExplicitAndBounded(){assertEquals(90,DirectClientStartup.timeout(Map.of()));assertEquals("thin",DirectClientStartup.kind(Map.of()));assertEquals("thick",DirectClientStartup.kind(Map.of("client_kind","thick")));for(Object value:List.of(0,9,181,10.5,"bad")){try{DirectClientStartup.timeout(Map.of("readiness_timeout_s",value));fail();}catch(IllegalArgumentException expected){}}try{DirectClientStartup.kind(Map.of("client_kind","auto"));fail();}catch(IllegalArgumentException expected){}}
}
